# POS Payment / ApplyStatus — the wallet's answer becomes sale state.
#   Succeeded (1): payment succeeded; when the sale is fully paid it completes (stock out, ledger).
#   Failed (2) / Expired (3): payment failed; the sale stays open so the teller can retry or take cash.
#   Pending (0): no change. Writes are guarded by changes() so two polls cannot finalise twice.
user = require_teller('''${IdpAuth}''')
actor = display_name(user)

def load_pay():
    rows = rows_of('''${Load}''')
    r = rows[0] if rows else {}
    settings = load_json(r.get('SettingsJson'), {}) or {}
    sale = load_json(r.get('SaleJson'), None)
    shift = load_json(r.get('ShiftJson'), None)
    if isinstance(sale, dict):
        sale['Items'] = load_json(sale.get('ItemsJson'), []) or []
        for k in ('Pending', 'Succeeded'):
            if isinstance(sale.get(k), str):
                sale[k] = load_json(sale.get(k), None)
    return settings, (sale if isinstance(sale, dict) and sale.get('Id') else None), (shift if isinstance(shift, dict) and shift.get('Id') else None)


def stock_out_guarded(actor):
    return [
        "UPDATE products SET StockQty = StockQty - (SELECT COALESCE(SUM(i.Qty), 0) FROM sale_items i WHERE i.SaleId = {SID} AND i.ProductId = products.Id), UpdatedAt = CURRENT_TIMESTAMP "
        "WHERE TrackInventory = 1 AND Id IN (SELECT ProductId FROM sale_items WHERE SaleId = {SID}){GUARD};",
        "INSERT INTO inventory_movements (ProductId, Delta, Reason, Reference, Note, CreatedBy) "
        "SELECT i.ProductId, -i.Qty, 'sale', (SELECT Reference FROM sales WHERE Id = {SID}), 'Sale (card)', " + q(actor) + " FROM sale_items i JOIN products p ON p.Id = i.ProductId WHERE i.SaleId = {SID} AND p.TrackInventory = 1{GUARD};",
    ]

settings, sale, shift = load_pay()
pay = load_json('''${WalletGet}''', None)
if not sale or not isinstance(pay, dict):
    fail('Sale or payment not found.')
pending = sale.get('Pending') or {}
sid = str(sale['Id'])
pid = str(to_int(pending.get('Id'), 0))
status = to_int(pay.get('Status'), 0)
raw = q(out(pay))
detail = "SELECT s.*, r.Name AS RegisterName, (SELECT json_group_array(json_object('Id', i.Id, 'ProductId', i.ProductId, 'Name', i.Name, 'Sku', i.Sku, 'Barcode', i.Barcode, 'Unit', i.Unit,    'Qty', i.Qty, 'UnitPriceCents', i.UnitPriceCents, 'DiscountCents', i.DiscountCents, 'TaxRateBp', i.TaxRateBp, 'TaxCents', i.TaxCents,    'LineTotalCents', i.LineTotalCents, 'RefundedQty', i.RefundedQty, 'Position', i.Position))  FROM (SELECT * FROM sale_items WHERE SaleId = s.Id ORDER BY Position, Id) i) AS ItemsJson, (SELECT json_group_array(json_object('Id', p.Id, 'Method', p.Method, 'AmountCents', p.AmountCents, 'TenderedCents', p.TenderedCents,    'ChangeCents', p.ChangeCents, 'Status', p.Status, 'Reference', p.Reference, 'ConnectPaymentId', p.ConnectPaymentId, 'PaymentUrl', p.PaymentUrl, 'CreatedAt', p.CreatedAt))  FROM (SELECT * FROM sale_payments WHERE SaleId = s.Id ORDER BY Id) p) AS PaymentsJson, (SELECT json_group_array(json_object('Id', f.Id, 'Reference', f.Reference, 'Method', f.Method, 'AmountCents', f.AmountCents, 'Reason', f.Reason, 'Status', f.Status, 'CreatedAt', f.CreatedAt))  FROM (SELECT * FROM refunds WHERE SaleId = s.Id ORDER BY Id) f) AS RefundsJson, (SELECT json_group_object(Key, Value) FROM settings WHERE Key IN ('store_name','store_tagline','store_address','store_phone','support_email','store_url','store_logo_url','store_icon_url','currency','tax_rate_bp','prices_include_tax','tax_number','receipt_header','receipt_footer','payment_cash_enabled','payment_card_enabled','allow_negative_stock','require_shift','quick_cash_amounts','theme_primary','theme_secondary')) AS SettingsJson FROM sales s LEFT JOIN registers r ON r.Id = s.RegisterId WHERE {where} LIMIT 1;".format(where="s.Id = " + sid).replace(" AS SettingsJson FROM sales", " AS SettingsJson, (SELECT v FROM _ctx WHERE k = 'fin') AS JustCompleted FROM sales")
amount = str(to_int(pending.get('AmountCents'), 0))
if status == 1:
    return "\n".join([
        "BEGIN;", "CREATE TEMP TABLE IF NOT EXISTS _ctx (k TEXT PRIMARY KEY, v INTEGER);", "DELETE FROM _ctx;",
        "UPDATE sale_payments SET Status = 'succeeded', RawJson = " + raw + ", UpdatedAt = CURRENT_TIMESTAMP WHERE Id = " + pid + " AND Status = 'pending';",
        "INSERT INTO _ctx (k, v) VALUES ('paid', changes());",
        "UPDATE sales SET PaidCents = PaidCents + " + amount + ", UpdatedAt = CURRENT_TIMESTAMP WHERE Id = " + sid + " AND (SELECT v FROM _ctx WHERE k = 'paid') = 1;",
        "UPDATE sales SET Status = 'completed', CompletedAt = CURRENT_TIMESTAMP WHERE Id = " + sid + " AND Status = 'open' AND PaidCents >= TotalCents AND (SELECT v FROM _ctx WHERE k = 'paid') = 1;",
        "INSERT INTO _ctx (k, v) VALUES ('fin', changes());",
    ] + [s.replace("{SID}", sid).replace("{GUARD}", " AND (SELECT v FROM _ctx WHERE k = 'fin') = 1") for s in stock_out_guarded(actor)] + [
        "INSERT INTO sale_events (SaleId, Type, Message, DataJson, CreatedBy) SELECT " + sid + ", 'card_paid', 'Card payment received', " + raw + ", 'system' WHERE (SELECT v FROM _ctx WHERE k = 'paid') = 1;",
        "COMMIT;",
        detail,
        "DROP TABLE IF EXISTS _ctx;",
    ])
if status in (2, 3):
