        "UPDATE sale_payments SET Status = " + q(label) + ", RawJson = " + raw + ", UpdatedAt = CURRENT_TIMESTAMP WHERE Id = " + pid + " AND Status = 'pending';",
        "INSERT INTO sale_events (SaleId, Type, Message, DataJson, CreatedBy) VALUES (" + sid + ", 'card_" + label + "', 'Card payment " + label + "', " + raw + ", 'system');",
