    ])
return "\n".join(["CREATE TEMP TABLE IF NOT EXISTS _ctx (k TEXT PRIMARY KEY, v INTEGER);", "DELETE FROM _ctx;", "INSERT INTO _ctx (k, v) VALUES ('fin', 0);",
                   "UPDATE sale_payments SET RawJson = " + raw + ", UpdatedAt = CURRENT_TIMESTAMP WHERE Id = " + pid + ";", detail, "DROP TABLE IF EXISTS _ctx;"])

