def _int_nonneg(v):
    n = to_int(v, None)
    return None if n is None or n < 0 else str(n)

def _text(maxlen):
    return lambda v: (str(v).strip()[:maxlen] if v is not None else None)

def _bool(v):
    return qb(v)

def _currency(v):
    s = str(v or '').strip().upper()
    return s if len(s) == 3 and s.isalpha() else None

