if op == 'set-status':
    pid = qi(d.get('id'), 0)
    st = str(d.get('status') or '').lower()
    if st not in ('active', 'inactive'):
        fail('Invalid status.')
    return "UPDATE products SET Status = " + q(st) + ", UpdatedAt = CURRENT_TIMESTAMP WHERE Id = " + pid + ";\n" + DETAIL.format(where="p.Id = " + pid)

if op == 'delete':
